{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "pricing",
      "host": "pricing.internal",
      "port": 8501,
      "weight": 1,
      "health_check": "/healthz"
    },
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 7220,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 9693,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "inventory",
      "host": "inventory.internal",
      "port": 7817,
      "weight": 4,
      "health_check": "/healthz"
    },
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 9505,
      "weight": 6,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/carts/quotes",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 3
    },
    {
      "path": "/api/v1/inventory/summary",
      "upstream": "inventory",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/pricing/batch",
      "upstream": "pricing",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 1
    },
    {
      "path": "/api/v1/inventory/batch",
      "upstream": "inventory",
      "methods": [
        "GET"
      ],
      "timeout_ms": 3000,
      "retries": 3
    },
    {
      "path": "/api/v1/inventory/history",
      "upstream": "inventory",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 3
    },
    {
      "path": "/api/v1/search/status",
      "upstream": "search",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 2
    },
    {
      "path": "/api/v1/carts/batch",
      "upstream": "carts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/carts/settings",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 3000,
      "retries": 1
    },
    {
      "path": "/api/v1/accounts/items",
      "upstream": "accounts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 3
    }
  ]
}

